from pathlib import Path
p=Path('packages/persistence/src/priority-national-source-coverage.ts')
s=p.read_text()
m='const CIPO: Authority = {'
assert m in s
b='''  target(IPOPHL_PH, {\n    id: "ph-ipophl-trademark-law",\n    family: "LEGAL_TEXTS",\n    displayName: "Philippines IPOPHL Trademark Laws and Regulations",\n    canonicalUri: "https://www.ipophil.gov.ph/intellectual-property-code-implementing-rules-and-regulations/",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "MARKDOWN", "PDF"],\n    verificationEvidenceUri: "https://www.ipophil.gov.ph/intellectual-property-code-implementing-rules-and-regulations/",\n    notes: "IPOPHL's primary legal-materials surface publishes the Intellectual Property Code and current implementing rules, including the 2023 trademark regulations replacing the revised 2017 regulations.",\n  }),\n  target(IPOPHL_PH, {\n    id: "ph-ipophl-trademark-examination-guidelines",\n    family: "EXAMINATION_MANUAL",\n    displayName: "Philippines IPOPHL Trademark Examination Guidelines",\n    canonicalUri: "https://www.ipophil.gov.ph/trademark/examination-guidelines/",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "PDF"],\n    verificationEvidenceUri: "https://www.ipophil.gov.ph/trademark/examination-guidelines/",\n    notes: "IPOPHL publishes dedicated trademark examination guidelines from the Bureau of Trademarks as an official examination and practice source.",\n  }),\n  target(IPOPHL_PH, {\n    id: "ph-ipophl-trademark-proceedings",\n    family: "PROCEEDINGS",\n    displayName: "Philippines IPOPHL Trademark Opposition and Cancellation Proceedings",\n    canonicalUri: "https://www.ipophil.gov.ph/services/ip-adjudication/",\n    entrypoints: [\n      { uri: "https://www.ipophil.gov.ph/services/ip-adjudication/", label: "Bureau of Legal Affairs inter-partes jurisdiction and rules" },\n      { uri: "https://www.ipophil.gov.ph/help-and-support/ip-adjudication-mediation-faqs/", label: "Online opposition/cancellation filing and hearing guidance" },\n    ],\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "MARKDOWN", "PDF"],\n    verificationEvidenceUri: "https://www.ipophil.gov.ph/services/ip-adjudication/",\n    notes: "IPOPHL's Bureau of Legal Affairs hears trademark oppositions and cancellation cases and publishes the governing Inter Partes rules; the official FAQ preserves current online filing and hearing routes.",\n  }),\n  target(IPOPHL_PH, {\n    id: "ph-ipophl-trademark-egazette",\n    family: "OFFICIAL_GAZETTE",\n    displayName: "Philippines IPOPHL Trademark Electronic Gazette",\n    canonicalUri: "https://onlineservices.ipophil.gov.ph/tmgazette/EG_HOME.ASP",\n    coverageTier: "CHANGE_SIGNAL",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "PDF"],\n    verificationEvidenceUri: "https://onlineservices.ipophil.gov.ph/tmgazette/EG_HOME.ASP",\n    notes: "IPOPHL continuously publishes trademark e-Gazette publication dates and related publication rules, with frequent 2026 issues, making it a high-value publication and change-signal source.",\n  }),\n] satisfies readonly SourceCoverageTarget[];\n\n'''
s=s.replace(m,b+m,1)
old='  ...MYIPO_MY_SOURCE_COVERAGE_TARGETS,\n  ...CIPO_SOURCE_COVERAGE_TARGETS,'
assert old in s
s=s.replace(old,'  ...MYIPO_MY_SOURCE_COVERAGE_TARGETS,\n  ...IPOPHL_PH_SOURCE_COVERAGE_TARGETS,\n  ...CIPO_SOURCE_COVERAGE_TARGETS,',1)
p.write_text(s)
